const RULES = [
  [/sales engineer|solutions engineer|sales|account executive|\bae\b|sdr|bdr|revenue|account manager|customer success|\bcsm\b|partnerships|gtm/i, 'Sales'],
  [/product manager|product design|\bproduct\b|\bpm\b|roadmap/i, 'Product'],
  [/design|\bux\b|\bui\b|brand designer|visual|creative director/i, 'Design'],
  [/marketing|growth|demand gen|content|\bseo\b|\bsem\b|brand|comms|communications|\bpr\b/i, 'Marketing'],
  [/people|talent|recruiter|recruiting|\bhr\b|human resources|people ops|workforce/i, 'People'],
  [/finance|accounting|controller|fp&a|treasury|payroll/i, 'Finance'],
  [/legal|counsel|compliance|privacy|policy/i, 'Legal'],
  [/operations|\bops\b|supply chain|logistics|business operations|strategy/i, 'Operations'],
  [/support|customer support|helpdesk|success engineer/i, 'Support'],
  [/data science|analytics|analyst|\bbi\b|business intelligence/i, 'Data'],
  [/engineer|engineering|software|backend|frontend|fullstack|full-stack|devops|sre|platform|infrastructure|data engineer|ml engineer|machine learning|security engineer|\bqa\b|quality assurance|developer|architect/i, 'Engineering'],
];
function labelDept(title, deptRaw) {
  const hay = `${title} ${deptRaw}`;
  for (const [re, lab] of RULES) {
    if (re.test(hay)) return lab;
  }
  if (deptRaw && String(deptRaw).trim()) return String(deptRaw).trim();
  return 'Other';
}
const all = items.flatMap(i => Array.isArray(i.json) ? i.json.map(j=>({json:j})) : [i]);
const scrapedAt = new Date().toISOString();
const out = [];
for (const it of all) {
  const j = it.json || {};
  const title = String(j.title || j.jobTitle || j.name || '');
  const deptRaw = String(j.department || j.team || '');
  if (!title) continue;
  const departmentLabel = labelDept(title, deptRaw);
  out.push({
    json: {
      company: j.company || j.companyName || '',
      title,
      department: deptRaw,
      departmentLabel,
      location: j.location || (Array.isArray(j.locations) ? j.locations.join('; ') : '') || '',
      jobUrl: j.url || j.jobUrl || j.source_url || j.apply_url || '',
      postedAt: j.published_at || j.postedAt || j.updated_at || '',
      ats: j.ats || 'greenhouse',
      scrapedAt,
      competitorWatchlist: 1
    }
  });
}
if (!out.length) {
  return [{json: {matched: 0, note: 'No jobs returned in this batch', scanned: all.length, scrapedAt}}];
}
return out.map(h => ({json: {...h.json, matched: 1, scanned: all.length}}));
